    Bug 493499 - Fix access key for 'Move to … again'. r=mkmelin


    While this fixes the underlying bug, it changes the access key from the
    `moveToFolderAgain.accesskey` defined in `messenger.dtd` ('i') to those
    defined in `messenger.properties` ('t'). In case of the message context menu,
    this duplicates the access key for 'Threads'.

    Differential Revision: https://phabricator.services.mozilla.com/D279509

diff --git a/mail/base/content/mailWindowOverlay.js b/mail/base/content/mailWindowOverlay.js
index c0852752994..7954baa5458 100644
--- a/mail/base/content/mailWindowOverlay.js
+++ b/mail/base/content/mailWindowOverlay.js
@@ -728,7 +728,7 @@ function initMoveToFolderAgainMenu(aMenuItem) {
     `${destMsgFolder.prettyPath} - ${destMsgFolder.server.prettyName}`
   );
   // This gives us moveToFolderAgainAccessKey and copyToFolderAgainAccessKey.
-  aMenuItem.accesskey = bundle.getString(stringName + "AccessKey");
+  aMenuItem.accessKey = bundle.getString(stringName + "AccessKey");
 }

